import type { ContextAssetInput } from '../agent-variants/contracts';
import type { GuidanceDocument, GuidanceSelection } from './guidance';
import type { ReferencePicks } from './design-profile';

export interface ChangeRequest {
  guidanceSelection?: GuidanceSelection;
  guidance?: GuidanceDocument[];
  guidanceAccountId?: string;
  changes: ChangeItem[];
  displayLocale?: string;
  initiator?: WorkItemInitiator;
  workerSelection?: WorkerSelection;
  target?: ChangeRequestTarget;
  worktreePath?: string;
  staticPreviewTarget?: StaticPreviewChangeTarget;
  sourceFiles: string[];
  telemetryContext?: TelemetryContext;
  traceId?: string;
  agentRunId?: string;
}

export interface TelemetryContext {
  browserSessionId?: string;
  browserDistinctId?: string;
}

export type CallerAgentKind =
  'claude' | 'codex' | 'cursor' | 'grokbot' | 'unknown';

export type WorkItemInitiator =
  { kind: 'human' } | { kind: 'agent'; agent: CallerAgentKind; model?: string };

export type WorkerProvider = 'claude' | 'codex' | 'cursor';

export interface WorkerSelection {
  provider?: WorkerProvider;
  model?: string;
}

export interface ChangeRequestTarget {
  kind: 'variant';
  sessionId: string;
  variantId: string;
}

export interface StaticPreviewChangeTarget {
  kind: 'static_preview';
  sessionId: string;
  variantId: string;
}

export type VariantRequestMode = 'existing' | 'zero_to_one';

export interface VariantDirectionBrief {
  label: string;
  body: string;
  notes?: string;
  visualReferenceUrl?: string;
}

export type ChangeItem =
  | StyleChangeItem
  | TextChangeItem
  | CommentChangeItem
  | ChatChangeItem
  | VariantChangeItem;

export interface StyleChangeItem {
  kind: 'style';
  element: ElementRef;
  property: string;
  from: string;
  to: string;
}

export interface TextChangeItem {
  kind: 'text';
  element: ElementRef;
  from: string;
  to: string;
}

export interface CommentChangeItem {
  profileContext?: string;
  profileTrace?: import('./design-profile').ProfileContextResult & {
    profileId?: string;
  };
  kind: 'comment';
  element: ElementRef;
  elements?: ElementRef[];
  target?: ChangeRequestTarget;
  staticPreviewTarget?: StaticPreviewChangeTarget;
  instruction: string;
  images?: string[];
  references?: CommentReferenceItem[];
  resolvedReferences?: ResolvedCommentReference[];
  variantRequest?: {
    guidanceSelection?: GuidanceSelection;
    profile?: 'auto' | 'off';
    count: number;
    mode?: VariantRequestMode;
    runLabel?: string;
    fidelity?: 'low' | 'medium' | 'high';
    briefs?: VariantDirectionBrief[];
    referencePages?: Array<{ url: string; note?: string }>;
    referenceVideos?: Array<{ path: string; note?: string }>;
    contextAssets?: ContextAssetInput[];
    referencePicks?: ReferencePicks;
  };
}

export interface CommentReferenceItem {
  sessionId: string;
  variantId: string;
  label: string;
  origin: 'live' | 'history';
}

export interface ResolvedCommentReference {
  sessionId: string;
  variantId: string;
  label: string;
  brief?: string;
  path: string;
  origin: 'live' | 'history';
}

export interface ChatChangeItem {
  kind: 'chat';
  instruction: string;
  images?: string[];
}

export interface VariantChangeItem {
  kind: 'variant';
  sourceSessionId: string;
  variantId: string;
  variantLabel: string;
  destinationPath: string;
  changedFilesCount: number;
  payload:
    | {
        kind: 'diff';
        diff: string;
        target?: { type: 'element' | 'file' | 'route'; ref: string };
      }
    | {
        kind: 'diff-applied';
        diff: string;
        target?: { type: 'element' | 'file' | 'route'; ref: string };
        note: string;
      }
    | {
        kind: 'project-created';
        note: string;
      };
}

export interface ElementRef {
  xpath: string;
  tagName: string;
  className: string;
  id: string;
  filePaths: string[];
  rivetId?: string;
  textContent?: string;
  attributes?: Record<string, string>;
  componentTree?: Array<{ name: string; type?: string; depth?: number }>;
  parentElementSummary?: {
    tagName: string;
    className: string;
    textSnippet: string;
  };
}
